nextflow_process {

    name "Test Process FQ_LINT"
    script "../main.nf"
    process "FQ_LINT"

    tag "modules"
    tag "modules_nfcore"
    tag "fq"
    tag "fq/lint"

    test("test_fq_lint_success") {
        when {
            params {
                outdir   = "$outputDir"
            }
            process {
                """
                input[0] = [ [ id:'test', single_end:false ], // meta map
                             [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                               file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true) ]
                           ]
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert process.out.lint.get(0).get(1) ==~ ".*/test.fq_lint.txt" },
                { assert path(process.out.lint.get(0).get(1)).getText().contains("fq-lint start") },
                { assert path(process.out.lint.get(0).get(1)).getText().contains("read 100 records") },
                { assert path(process.out.lint.get(0).get(1)).getText().contains("fq-lint end") },
            )
        }

    }

    test("test_fq_lint_rejects_more_than_two_fastqs") {
        when {
            params {
                outdir   = "$outputDir"
            }
            process {
                """
                def fq1 = file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                def fq2 = file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                def fq3 = file("\${workDir}/test_3.fastq.gz")
                fq3.bytes = fq1.bytes
                input[0] = [ [ id:'test', single_end:false ],
                             [ fq1, fq2, fq3 ]
                           ]
                """
            }
        }

        then {
            assertAll (
                { assert !process.success }
            )
        }

    }

    test("test_fq_lint_fail") {
        when {
            params {
                outdir   = "$outputDir"
            }
            process {
                """
                input[0] = [ [ id:'test', single_end:false ], // meta map
                             [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                               file(params.modules_testdata_base_path + 'genomics/prokaryotes/candidatus_portiera_aleyrodidarum/illumina/fastq/test_2.fastq.gz', checkIfExists: true) ]
                           ]
                """
            }
        }

        then {
            assertAll (
                { assert !process.success },
                { assert snapshot(
                    process.out.lint,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() },
            )
        }

    }

}
